-- Run against an isolated restored database only. All fixtures roll back.
\set ON_ERROR_STOP on
begin;
do $$ begin if current_database()<>'t2q_release_audit_20260913' then raise exception 'Isolated test database required'; end if; end $$;
create function pg_temp.assert_true(ok boolean, label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create function pg_temp.assert_rejected(statement text, expected text) returns void language plpgsql as $$ begin begin execute statement; exception when others then if position(expected in sqlerrm)>0 then raise notice 'PASS: rejected %',expected; return; end if; raise; end; raise exception 'FAIL: statement was allowed: %',statement; end $$;
insert into auth.users(id,email,email_confirmed_at,aud,role,created_at,updated_at)
select ('a1000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,'t2q-fixture-'||i||'@example.invalid',now(),'authenticated','authenticated',now(),now() from generate_series(1,12)i;
insert into public.subscriptions(user_id,stripe_customer_id,plan,status,current_period_end)
values('a1000000-0000-0000-0000-000000000001','cus_team_fixture','crew','active',now()+interval '30 days'),('a1000000-0000-0000-0000-000000000010','cus_builder_fixture','builder','active',now()+interval '30 days');
insert into public.clients(user_id,name,email) values('a1000000-0000-0000-0000-000000000001','Shared fixture','client@example.invalid'),('a1000000-0000-0000-0000-000000000002','Personal fixture','private@example.invalid');
insert into public.quotes(id,user_id,quote_data,status) values('b1000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000001','{}','draft');
set local role authenticated;
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000001',true);
select public.manage_team('create','{"name":"Fixture Crew"}');
select public.manage_team('invite',jsonb_build_object('email','t2q-fixture-2@example.invalid','token_hash',repeat('a',64)));
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000003',true);
select pg_temp.assert_rejected(format('select public.manage_team(''accept'',''{"token_hash":"%s"}'')',repeat('a',64)),'verified email');
select pg_temp.assert_true((select count(*) from public.clients)=0,'unrelated account cannot see clients');
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000002',true);
select public.manage_team('accept',jsonb_build_object('token_hash',repeat('a',64)));
select pg_temp.assert_true(public.my_team_owner()='a1000000-0000-0000-0000-000000000001','accepted member inherits team');
select pg_temp.assert_true((select count(*) from public.clients)=2,'member sees shared and their own records only');
select pg_temp.assert_true((select count(*) from public.quotes)=0,'team membership does not expose owner quotes');
select pg_temp.assert_rejected('select public.manage_team(''invite'',''{"email":"t2q-fixture-3@example.invalid"}'')','Only the team owner');
select public.save_client_contact('{"name":"Member saved","email":"new@example.invalid"}');
select pg_temp.assert_true((select user_id from public.clients where email='new@example.invalid')='a1000000-0000-0000-0000-000000000001','member saves to shared book');
select pg_temp.assert_rejected(format('select public.manage_team(''accept'',''{"token_hash":"%s"}'')',repeat('a',64)),'invalid or has expired');
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000001',true);
select public.manage_team('invite',jsonb_build_object('email','t2q-fixture-3@example.invalid','token_hash',repeat('b',64)));
select public.manage_team('invite',jsonb_build_object('email','t2q-fixture-4@example.invalid','token_hash',repeat('c',64)));
select public.manage_team('invite',jsonb_build_object('email','t2q-fixture-5@example.invalid','token_hash',repeat('d',64)));
select pg_temp.assert_rejected(format('select public.manage_team(''invite'',''{"email":"t2q-fixture-6@example.invalid","token_hash":"%s"}'')',repeat('e',64)),'All seats');
select pg_temp.assert_rejected('select public.manage_team(''remove'',''{"user_id":"a1000000-0000-0000-0000-000000000001"}'')','owner cannot be removed');
select pg_temp.assert_rejected('insert into public.terms_templates(user_id,title,body) values(auth.uid(),''Crew template'',''Not allowed'')','row-level security');
select public.manage_team('revoke',jsonb_build_object('id',(select id from public.team_invitations where token_hash=repeat('b',64))));
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000003',true);
select pg_temp.assert_rejected(format('select public.manage_team(''accept'',''{"token_hash":"%s"}'')',repeat('b',64)),'invalid or has expired');
reset role;
update public.team_invitations set expires_at=now()-interval '1 day' where token_hash=repeat('c',64);
update public.subscriptions set status='canceled' where stripe_customer_id='cus_team_fixture';
set local role authenticated;
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000004',true);
select pg_temp.assert_rejected(format('select public.manage_team(''accept'',''{"token_hash":"%s"}'')',repeat('c',64)),'invalid or has expired');
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000002',true);
select pg_temp.assert_true(public.my_team_owner() is null,'cancellation revokes team entitlement');
select pg_temp.assert_true((select count(*) from public.clients)=1,'cancelled team cannot see shared book');
select pg_temp.assert_true((select count(*) from public.teams)=1,'inactive member can still see their team to leave');
reset role;
update public.subscriptions set status='active',current_period_end=now()-interval '1 day' where stripe_customer_id='cus_team_fixture';
set local role authenticated;
select pg_temp.assert_true(public.my_team_owner() is null,'expired period cannot grant team access');
reset role;
update public.subscriptions set current_period_end=now()+interval '30 days' where stripe_customer_id='cus_team_fixture';
set local role authenticated;
select pg_temp.assert_true(public.my_team_owner() is not null,'renewed period restores team access');
select public.manage_team('leave');
select pg_temp.assert_true(public.my_team_owner() is null,'leaving revokes shared access');
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000010',true);
insert into public.terms_templates(user_id,title,body) values(auth.uid(),'Payment terms','Fixture terms');
select pg_temp.assert_true((select count(*) from public.terms_templates)=1,'Builder can save terms');
select public.manage_team('create','{"name":"Fixture Builder"}');
reset role;
insert into public.team_members(user_id,team_id) select ('a1000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,(select id from public.teams where owner_id='a1000000-0000-0000-0000-000000000010') from generate_series(2,7)i;
update public.subscriptions set plan='crew' where stripe_customer_id='cus_builder_fixture';
set local role authenticated;
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000002',true);
select pg_temp.assert_true(public.my_team_owner() is null,'downgrade beyond seat limit revokes member entitlement');
select pg_temp.assert_true((select count(*) from public.terms_templates)=0,'downgraded plan hides Builder templates');
-- Checkout mutex remains held until the exact lease is released.
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000011',true);
select public.claim_checkout('crew');
select pg_temp.assert_rejected('select public.claim_checkout(''builder'')','Checkout is opening');
reset role;
select public.finish_checkout((select key from public.checkout_attempts where user_id='a1000000-0000-0000-0000-000000000011'));
set local role authenticated;
select public.claim_checkout('builder');
reset role;
-- Stripe writes are atomic and reject stale subscription generations or snapshots.
select public.sync_stripe_subscription(jsonb_build_object('id','sub_new','customer','cus_team_fixture','user_id','a1000000-0000-0000-0000-000000000001','plan','builder','status','active','created',200,'observed_at','2026-09-13T00:02:00Z','period_end',now()+interval '30 days'));
select public.sync_stripe_subscription(jsonb_build_object('id','sub_old','customer','cus_team_fixture','plan','solo','status','canceled','created',100,'observed_at','2026-09-13T00:03:00Z'));
select pg_temp.assert_true((select plan='builder' and status='active' from public.subscriptions where stripe_customer_id='cus_team_fixture'),'old subscription cannot overwrite new subscription');
select public.sync_stripe_subscription(jsonb_build_object('id','sub_new','customer','cus_team_fixture','plan','crew','status','past_due','created',200,'observed_at','2026-09-13T00:01:00Z'));
select pg_temp.assert_true((select plan='builder' from public.subscriptions where stripe_customer_id='cus_team_fixture'),'older API read cannot overwrite latest plan');
select pg_temp.assert_rejected('select public.sync_stripe_subscription(''{"id":"sub_new","customer":"cus_team_fixture","user_id":"a1000000-0000-0000-0000-000000000002"}'')','does not match');
-- Photos are capped, owner-scoped and immutable once sent.
select public.register_quote_photo(jsonb_build_object('quote_id','b1000000-0000-0000-0000-000000000001','user_id','a1000000-0000-0000-0000-000000000001','path','a1000000-0000-0000-0000-000000000001/b1000000-0000-0000-0000-000000000001/'||i||'.jpg','name','Fixture')) from generate_series(1,8)i;
select pg_temp.assert_rejected('select public.register_quote_photo(''{"quote_id":"b1000000-0000-0000-0000-000000000001","user_id":"a1000000-0000-0000-0000-000000000001"}'')','Maximum 8');
update public.quotes set status='sent' where id='b1000000-0000-0000-0000-000000000001';
select pg_temp.assert_rejected('select public.register_quote_photo(''{"quote_id":"b1000000-0000-0000-0000-000000000001","user_id":"a1000000-0000-0000-0000-000000000001"}'')','Only draft');
select pg_temp.assert_rejected(format('select public.remove_quote_photo(%L,%L)',(select id from public.quote_attachments limit 1),'a1000000-0000-0000-0000-000000000001'),'Only draft');
rollback;
